    const transactionId = (lines[0] || "").trim();
    if (!/^TXN-[0-9a-f-]+$/i.test(transactionId)) continue;

    const row = {
      transaction_id: transactionId,
      owner: "",
      status: "",
      date: "",
      amount: null,
      provisional: false,
    };

    for (const line of lines.slice(1)) {
      const trimmed = line.trim();
      let m;
      if ((m = trimmed.match(/^amount:\s*([0-9]+(?:\.[0-9]+)?)\s*$/i))) {
        row.amount = Number(m[1]);
      } else if ((m = trimmed.match(/^owner:\s*(.+)\s*$/i))) {
        row.owner = m[1].trim();
      } else if ((m = trimmed.match(/^status:\s*(\w+)\s*$/i))) {
        row.status = m[1].trim().toLowerCase();
      } else if ((m = trimmed.match(/^date:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*$/i))) {
