const { parseLedger } = require("./ledger");
const { parseMeetings } = require("./meetings");
const { parseEmails } = require("./emails");
const { parseCorrections } = require("./corrections");
const { parsePolicyExceptions } = require("./policy");

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function sliceSection(markdown, headingLine) {
  const startRe = new RegExp(`^${escapeRegex(headingLine)}\\s*$`, "m");
  const startMatch = markdown.match(startRe);
  if (!startMatch || startMatch.index == null) return "";
  const startIdx = startMatch.index;

  // Next heading at the same level (## ...)
  const rest = markdown.slice(startIdx + startMatch[0].length);
  const nextRe = /^##\s+.+\s*$/m;
  const nextMatch = rest.match(nextRe);
  const endIdx = nextMatch && nextMatch.index != null ? startIdx + startMatch[0].length + nextMatch.index : markdown.length;
  return markdown.slice(startIdx, endIdx);
}

function parseArchive(markdown) {
  const meetingsSection = sliceSection(markdown, "## Meeting Notes");
  const emailsSection = sliceSection(markdown, "## Email Excerpts");
  const policySection = sliceSection(markdown, "## Policy Exceptions");
  const correctionsSection = sliceSection(markdown, "## Correction Notices");
  const ledgerSection = sliceSection(markdown, "## Transaction Ledger");

  return {
    ledger: parseLedger(ledgerSection),
    meetings: parseMeetings(meetingsSection),
    emails: parseEmails(emailsSection),
    corrections: parseCorrections(correctionsSection),
    policyExceptions: parsePolicyExceptions(policySection),
  };
}

module.exports = { parseArchive, sliceSection };
