function parseBool(s) {
  if (s == null) return false;
  return String(s).trim().toLowerCase() === "true";
}

function parseLedger(markdown) {
  if (!markdown) return [];

  // Expect markdown already sliced to the canonical section whose heading line is exactly:
  // ## Transaction Ledger
  const rowsById = new Map();

  const blocks = markdown.split(/^###\s+/m).slice(1);
  for (const block of blocks) {
    const lines = block.split(/\r?\n/);
    const transactionId = (lines[0] || "").trim();
    if (!/^TXN-[0-9a-f-]+$/i.test(transactionId)) continue;

    const row = {
      transaction_id: transactionId,
      owner: "",
      status: "",
      date: "",
      amount: null,
      provisional: false,
    };

    for (const line of lines.slice(1)) {
      const trimmed = line.trim();
      let m;
      if ((m = trimmed.match(/^amount:\s*([0-9]+(?:\.[0-9]+)?)\s*$/i))) {
        row.amount = Number(m[1]);
      } else if ((m = trimmed.match(/^owner:\s*(.+)\s*$/i))) {
        row.owner = m[1].trim();
      } else if ((m = trimmed.match(/^status:\s*(\w+)\s*$/i))) {
        row.status = m[1].trim().toLowerCase();
      } else if ((m = trimmed.match(/^date:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*$/i))) {
        row.date = m[1];
      } else if ((m = trimmed.match(/^provisional:\s*(true|false)\s*$/i))) {
        row.provisional = parseBool(m[1]);
      }
    }

    if (row.provisional) continue;

    // Keep last non-provisional block in file order.
    rowsById.set(row.transaction_id, row);
  }

  return [...rowsById.values()];
}

module.exports = { parseLedger };
EOF
