const { sortByTransactionId } = require("../utils/sort");

// Status precedence (lowest to highest) per handbook.
const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function cmpStatus(a, b) {
  const av = STATUS_ORDER[String(a || "").toLowerCase()];
  const bv = STATUS_ORDER[String(b || "").toLowerCase()];
  if (av == null || bv == null) return null;
  return av - bv;
}

function reconcileTransactions(parsed) {
  const byId = new Map();

  // Base ledger rows (ledger parser already keeps last non-provisional per id)
  for (const row of parsed.ledger || []) {
    byId.set(row.transaction_id, {
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status).toLowerCase(),
      date: row.date,
      amount: Number(row.amount),
      ledger_date: row.date,
    });
  }

  // Amendments (owner) - only signed:true, and effective>=ledger date when present
  for (const amend of parsed.meetings || []) {
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (!amend.signed) continue;
    if (amend.effective && amend.effective < target.ledger_date) continue;
    if (amend.owner) target.owner = amend.owner;
  }

  // Emails (status) - only compliance@, only when moving up precedence
  // sent condition: if present, apply only when sent>=ledger date
  const qualifyingComplianceSentEmail = new Set();
  for (const email of parsed.emails || []) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;

    const from = String(email.from_addr || "");
    if (!from.includes("compliance@")) continue;

    if (email.sent) {
      if (email.sent < target.ledger_date) continue;
      qualifyingComplianceSentEmail.add(email.transaction_id);
    }

    const current = String(target.status).toLowerCase();
    const incoming = String(email.status).toLowerCase();
    const delta = cmpStatus(current, incoming);
    if (delta == null) continue;
    if (delta < 0) {
      // incoming is higher precedence
      target.status = incoming;
    }
  }

  // Policy exceptions: map txn -> approved_by
  const policyByTxn = new Map();
  for (const ex of parsed.policyExceptions || []) {
    if (!ex || !ex.transaction_id) continue;
    policyByTxn.set(ex.transaction_id, ex);
  }

  // Corrections: choose winning notice per (txn, field) by lexicographically greatest effective date
  const winningByTxnField = new Map();
  for (const notice of parsed.corrections || []) {
    const key = `${notice.transaction_id}::${notice.field}`;
    const prev = winningByTxnField.get(key);
    if (!prev || String(notice.effective) > String(prev.effective)) {
      winningByTxnField.set(key, notice);
    }
  }

  // Apply winning corrections, but report must be sorted by notice_id and needs previous_value.
  // We apply in effective order per txn (and stable by field) so previous_value reflects actual state.
  const winningNotices = [...winningByTxnField.values()];
  winningNotices.sort((a, b) => {
    if (a.transaction_id !== b.transaction_id) return a.transaction_id < b.transaction_id ? -1 : 1;
    if (a.effective !== b.effective) return a.effective < b.effective ? -1 : 1;
    if (a.field !== b.field) return a.field < b.field ? -1 : 1;
    return a.notice_id < b.notice_id ? -1 : 1;
  });

  const report = [];
  const txnHadWinningStatusCorrection = new Set();
  const txnEffectiveOverride = new Map(); // txn -> max effective among winning corrections touching status/date

  for (const notice of winningNotices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let previousValue = "";
    const field = notice.field;

    if (field === "owner") {
      previousValue = target.owner;
      target.owner = notice.value;
    } else if (field === "status") {
      previousValue = target.status;
      target.status = String(notice.value).toLowerCase();
      txnHadWinningStatusCorrection.add(notice.transaction_id);
      const cur = txnEffectiveOverride.get(notice.transaction_id);
      if (!cur || notice.effective > cur) txnEffectiveOverride.set(notice.transaction_id, notice.effective);
    } else if (field === "date") {
      previousValue = target.date;
      target.date = notice.value;
      const cur = txnEffectiveOverride.get(notice.transaction_id);
      if (!cur || notice.effective > cur) txnEffectiveOverride.set(notice.transaction_id, notice.effective);
    } else {
      continue;
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field,
      previous_value: previousValue,
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  // Now compute outputs, including effective_date and exception_reason
  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const amount = Number(row.amount);
      const finalStatus = String(row.status).toLowerCase();

      const effective_date = txnEffectiveOverride.get(row.transaction_id) || row.ledger_date;

      const reasons = [];
      if (amount > 10000) reasons.push("over_limit");

      if (finalStatus === "rejected" && qualifyingComplianceSentEmail.has(row.transaction_id)) {
        reasons.push("compliance_hold");
      }

      const pol = policyByTxn.get(row.transaction_id);
      if (
        finalStatus === "approved" &&
        amount > 10000 &&
        pol &&
        String(pol.approved_by || "").toLowerCase() === "compliance"
      ) {
        reasons.push("policy_waiver");
      }

      if (
        finalStatus === "reversed" &&
        amount > 5000 &&
        txnHadWinningStatusCorrection.has(row.transaction_id)
      ) {
        reasons.push("retroactive_review");
      }

      reasons.sort();
      const exception_reason = reasons.length ? reasons.join(";") : null;

      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: finalStatus,
        effective_date,
        amount_usd: Number(amount.toFixed(2)),
        exception_reason,
      };
    }),
  );

  report.sort((a, b) => (a.notice_id < b.notice_id ? -1 : 1));

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER };
EOF
