        row.amount = Number(m[1]);
      } else if ((m = trimmed.match(/^owner:\s*(.+)\s*$/i))) {
        row.owner = m[1].trim();
      } else if ((m = trimmed.match(/^status:\s*(\w+)\s*$/i))) {
        row.status = m[1].trim().toLowerCase();
      } else if ((m = trimmed.match(/^date:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*$/i))) {
        row.date = m[1];
      } else if ((m = trimmed.match(/^provisional:\s*(true|false)\s*$/i))) {
        row.provisional = parseBool(m[1]);
      }
    }

    if (row.provisional) continue;

    // Keep last non-provisional block in file order.
    rowsById.set(row.transaction_id, row);
  }

  return [...rowsById.values()];
}

