function parseMeetings(markdown) {
  if (!markdown) return [];
  const amendments = [];

  const re = /^####\s+Amendment\s+for\s+(TXN-[0-9a-f-]+)\s*$/gim;
  let match;
  while ((match = re.exec(markdown)) !== null) {
    const start = match.index;
    const rest = markdown.slice(start);
    const nextHeadingIdx = rest.slice(match[0].length).search(/^####\s+/m);
    const block = nextHeadingIdx >= 0 ? rest.slice(0, match[0].length + nextHeadingIdx) : rest;

    const ownerMatch = block.match(/^owner:\s*(.+)\s*$/im);
    const signedMatch = block.match(/^signed:\s*(true|false)\s*$/im);
    const effMatch = block.match(/^effective:\s*([0-9]{4}-[0-9]{2}-[0-9]{2})\s*$/im);

    amendments.push({
      transaction_id: match[1],
      owner: ownerMatch ? ownerMatch[1].trim() : "",
      signed: signedMatch ? String(signedMatch[1]).trim().toLowerCase() === "true" : false,
      effective: effMatch ? effMatch[1] : null,
    });
  }

  return amendments;
}

module.exports = { parseMeetings };
